import os
import random
import struct
from typing import List

# This generator focuses on producing valid and interesting raw byte buffers
# for CRC and SHA-256 update/signing related fuzzers. It crafts a mix of sizes
# and content patterns to exercise edge cases while remaining valid arbitrary bytes.

MAX_SIZE = 2048  # keep under fuzzer caps and requirement (<=4096)

def _rand_bytes(rng: random.Random, n: int) -> bytes:
    # Mix biased distributions: printable, zeros, 0xFF, incremental, random
    modes = [
        "random", "zeros", "ff", "inc", "dec", "ascii", "pattern16", "pattern32", "repeated_block"
    ]
    mode = rng.choice(modes)
    if n <= 0:
        return b""
    if mode == "random":
        return bytes(rng.getrandbits(8) for _ in range(n))
    if mode == "zeros":
        return b"\x00" * n
    if mode == "ff":
        return b"\xFF" * n
    if mode == "inc":
        start = rng.randrange(256)
        return bytes((start + i) & 0xFF for i in range(n))
    if mode == "dec":
        start = rng.randrange(256)
        return bytes((start - i) & 0xFF for i in range(n))
    if mode == "ascii":
        # Mix of digits, letters, punctuation, and nulls
        alphabet = (b"0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ!@#$%^&*()-_=+[]{};:'\",.<>/?|`~\0")
        return bytes(alphabet[rng.randrange(len(alphabet))] for _ in range(n))
    if mode == "pattern16":
        a = rng.getrandbits(8)
        b = rng.getrandbits(8)
        pat = bytes([a, b])
        return (pat * (n // 2) + pat[: n % 2])
    if mode == "pattern32":
        vals = [rng.getrandbits(8) for _ in range(4)]
        pat = bytes(vals)
        q, r = divmod(n, 4)
        return pat * q + pat[:r]
    if mode == "repeated_block":
        blen = rng.choice([3,4,8,16,32])
        block = bytes(rng.getrandbits(8) for _ in range(blen))
        q, r = divmod(n, blen)
        return block * q + block[:r]
    return bytes(rng.getrandbits(8) for _ in range(n))

def _compose_sections(rng: random.Random) -> bytes:
    # Build a buffer as concatenation of sections to mimic headers/payloads/signature spaces
    sections: List[bytes] = []

    # Optionally prepend MAVLink-like header (not required to be valid, but shaped)
    if rng.random() < 0.7:
        # magic, len, inc/compat flags, seq, sysid, compid, 3-byte msgid
        magic = rng.choice([0xFE, 0xFD, rng.randrange(256)])
        length = rng.randrange(0, 256)
        inc_flags = rng.getrandbits(8)
        compat_flags = rng.getrandbits(8)
        seq = rng.getrandbits(8)
        sysid = rng.randrange(1, 256) if rng.random() < 0.8 else rng.getrandbits(8)
        compid = rng.randrange(1, 256) if rng.random() < 0.8 else rng.getrandbits(8)
        msgid = rng.getrandbits(24)
        hdr = bytes([
            magic,
            length,
            inc_flags,
            compat_flags,
            seq,
            sysid,
            compid,
            msgid & 0xFF,
            (msgid >> 8) & 0xFF,
            (msgid >> 16) & 0xFF,
        ])
        sections.append(hdr)

    # Payload: choose size correlated with header len sometimes
    if sections and len(sections[0]) >= 2:
        target_len = sections[0][1]  # header length field
        # choose actual from {0, target_len, random}
        choice = rng.random()
        if choice < 0.3:
            pay = _rand_bytes(rng, 0)
        elif choice < 0.7:
            pay = _rand_bytes(rng, target_len)
        else:
            pay = _rand_bytes(rng, rng.randrange(0, min(MAX_SIZE, 3*target_len + 1)))
    else:
        pay = _rand_bytes(rng, rng.randrange(0, MAX_SIZE//2 + 1))
    sections.append(pay)

    # Optionally append 2-byte CRC
    if rng.random() < 0.9:
        # Either random CRC or X25 over payload for variety
        if rng.random() < 0.5:
            crc = rng.getrandbits(16)
            sections.append(struct.pack('<H', crc))
        else:
            crc = _crc_x25(pay)
            sections.append(struct.pack('<H', crc))

    # Optionally append a 13-byte signature block skeleton (link id + timestamp(6) + sig(6))
    if rng.random() < 0.5:
        link_id = rng.randrange(0, 4)
        ts = rng.getrandbits(48)
        sig6 = bytes(rng.getrandbits(8) for _ in range(6))
        sig = bytes([link_id]) + ts.to_bytes(6, 'little') + sig6
        sections.append(sig)

    # Mix in some padding or secondary random chunk to exercise crc_accumulate_buffer
    if rng.random() < 0.4:
        sections.append(_rand_bytes(rng, rng.randrange(0, 64)))

    blob = b"".join(sections)
    if len(blob) > MAX_SIZE:
        blob = blob[:MAX_SIZE]
    return blob

def _crc_x25(data: bytes) -> int:
    # CRC-16/MCRF4XX (X.25) parameters: poly 0x1021, init 0xFFFF, refin/refout true, xorout 0xFFFF
    crc = 0xFFFF
    for b in data:
        tmp = b ^ (crc & 0xFF)
        tmp ^= (tmp << 4) & 0xFF
        crc = ((crc >> 8) ^ (tmp << 8) ^ (tmp << 3) ^ (tmp >> 4)) & 0xFFFF
    return crc & 0xFFFF

def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    # Decide overall strategy: single-pattern buffer vs composed MAVLink-shaped buffer
    strategy = rng.random()

    if strategy < 0.25:
        # Edge cases: empty to small sizes
        size = rng.choice([0, 1, 2, 3, 4, 7, 8, 15, 16, 31, 32, 63, 64])
        return _rand_bytes(rng, size)
    elif strategy < 0.5:
        # Medium sizes with patterned content
        size = rng.randrange(1, 513)
        return _rand_bytes(rng, size)
    elif strategy < 0.8:
        # Composed sections emulating header/payload/crc/signature
        return _compose_sections(rng)
    else:
        # Large but capped buffer, with a structure: header, several chunks accumulated
        chunks: List[bytes] = []
        # optional header-like prefix
        chunks.append(_compose_sections(rng)[:32])
        total = sum(len(c) for c in chunks)
        while total < MAX_SIZE and rng.random() < 0.7:
            part_len = rng.randrange(1, min(256, MAX_SIZE - total + 1))
            chunk = _rand_bytes(rng, part_len)
            chunks.append(chunk)
            total += len(chunk)
        blob = b"".join(chunks)
        if len(blob) > MAX_SIZE:
            blob = blob[:MAX_SIZE]
        return blob
